'use strict';
/**
 * Optional encrypted keystore for a mining address generated by the panel.
 *
 * The private key is encrypted with a key derived from the panel password
 * (scrypt) using AES-256-GCM. It is only decrypted when the user explicitly
 * asks to view it, after re-entering the password.
 *
 * Generating keys inside a web panel is a convenience, not a requirement:
 * pointing the miner at an address created by any Kaspa wallet works fine.
 */
const crypto = require('node:crypto');
const path = require('node:path');
const { DATA_DIR, readJson, writeJson } = require('./util');
const { generateWallet, addressFromPrivateKey } = require('./address');

const WALLET_FILE = path.join(DATA_DIR, 'wallet.json');

function deriveKey(password, salt) {
  return crypto.scryptSync(password, salt, 32, { N: 1 << 15, r: 8, p: 1, maxmem: 128 * (1 << 15) * 8 * 2 });
}

function encryptPrivateKey(privateKeyHex, password) {
  const salt = crypto.randomBytes(16);
  const iv = crypto.randomBytes(12);
  const key = deriveKey(password, salt);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  const data = Buffer.concat([cipher.update(Buffer.from(privateKeyHex, 'hex')), cipher.final()]);
  return {
    salt: salt.toString('hex'),
    iv: iv.toString('hex'),
    tag: cipher.getAuthTag().toString('hex'),
    data: data.toString('hex'),
  };
}

function decryptPrivateKey(record, password) {
  const salt = Buffer.from(record.salt, 'hex');
  const iv = Buffer.from(record.iv, 'hex');
  const key = deriveKey(password, salt);
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(Buffer.from(record.tag, 'hex'));
  const out = Buffer.concat([decipher.update(Buffer.from(record.data, 'hex')), decipher.final()]);
  return out.toString('hex');
}

function readWallet() {
  return readJson(WALLET_FILE, null);
}

function createWallet({ network, password }) {
  if (!password) throw new Error('a panel password is required to store a wallet');
  const keypair = generateWallet(network);
  const record = {
    v: 1,
    address: keypair.address,
    network: keypair.network,
    publicKey: keypair.publicKeyHex,
    createdAt: new Date().toISOString(),
    ...encryptPrivateKey(keypair.privateKeyHex, password),
  };
  writeJson(WALLET_FILE, record);
  return { address: keypair.address, privateKeyHex: keypair.privateKeyHex, network: keypair.network };
}

function importWallet({ privateKeyHex, network, password }) {
  const derived = addressFromPrivateKey(privateKeyHex, network);
  writeJson(WALLET_FILE, {
    v: 1,
    address: derived.address,
    network: derived.network,
    publicKey: derived.publicKeyHex,
    createdAt: new Date().toISOString(),
    ...encryptPrivateKey(privateKeyHex, password),
  });
  return { address: derived.address, privateKeyHex, network: derived.network };
}

/** Called on password change so the keystore keeps working. */
function reencryptWallet({ oldPassword, newPassword }) {
  const record = readWallet();
  if (!record || !record.data) return false;
  const privateKeyHex = decryptPrivateKey(record, oldPassword);
  writeJson(WALLET_FILE, { ...record, ...encryptPrivateKey(privateKeyHex, newPassword) });
  return true;
}

function walletSummary() {
  const record = readWallet();
  if (!record || !record.address) return { exists: false };
  return {
    exists: true,
    address: record.address,
    network: record.network,
    createdAt: record.createdAt,
    publicKey: record.publicKey,
  };
}

function revealPrivateKey(password) {
  const record = readWallet();
  if (!record || !record.data) throw new Error('No wallet stored in this panel');
  return decryptPrivateKey(record, password);
}

module.exports = {
  WALLET_FILE,
  createWallet,
  importWallet,
  walletSummary,
  revealPrivateKey,
  reencryptWallet,
};
